R=Path('/workspace/wewa');source,out=sys.argv[sys.argv.index('--')+1:][:2];p=R/source;bpy.ops.wm.open_mainfile(filepath=str(p));meshes=[o for o in bpy.data.objects if o.type=='MESH'];roots={o.name:[c.name for c in o.users_collection]for o in meshes};d={'source':source,'source_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'source_bytes':p.stat().st_size,'scene_root_collection':bpy.context.scene.collection.name,'data_collections':[c.name for c in bpy.data.collections],'mesh_objects':roots,'libraries':[str(l.filepath)for l in bpy.data.libraries],'images':[{'name':i.name,'filepath':i.filepath,'packed':bool(i.packed_file)}for i in bpy.data.images if i.type!='RENDER_RESULT']};O=R/out;O.parent.mkdir(parents=True,exist_ok=True);O.write_text(json.dumps(d,indent=2));print(json.dumps(d))
